import{_ as t,o as r,c as a,ah as o}from"./chunks/framework.DDXs_i7t.js";const g=JSON.parse('{"title":"The Cast: The Best for the Mystery","description":"","frontmatter":{},"headers":[],"relativePath":"en/cast.md","filePath":"en/cast.md"}'),s={name:"en/cast.md"};function i(n,e,h,m,l,u){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="the-cast-the-best-for-the-mystery" tabindex="-1">The Cast: The Best for the Mystery <a class="header-anchor" href="#the-cast-the-best-for-the-mystery" aria-label="Permalink to &quot;The Cast: The Best for the Mystery&quot;">​</a></h1><p>For our mockumentary, we&#39;ve secured some of the most prominent faces in German-language cinema. They don&#39;t just play their roles; they inhabit the absurdity of their characters.</p><h2 id="birgit-minichmayr-as-heidi-goess-horten" tabindex="-1"><a href="https://www.imdb.com/name/nm0591352/" target="_blank" rel="noreferrer">Birgit Minichmayr</a> as <em>Heidi Goëss-Horten</em> <a class="header-anchor" href="#birgit-minichmayr-as-heidi-goess-horten" aria-label="Permalink to &quot;[Birgit Minichmayr](https://www.imdb.com/name/nm0591352/) as *Heidi Goëss-Horten*&quot;">​</a></h2><p><strong>The Role:</strong> The Grande Dame of Lake Wörthersee.</p><p><strong>The Performance:</strong> Minichmayr plays Heidi with a mix of razor-sharp irony and disarming friendliness. She manages to present the &quot;donation splitting&quot; as an act of pure artistic benevolence. Her Heidi is both a victim of her own luxury and the director of a political system.</p><h2 id="august-diehl-as-helmut-horten-the-young-helmut" tabindex="-1"><a href="https://www.imdb.com/name/nm0225944/" target="_blank" rel="noreferrer">August Diehl</a> as <em>Helmut Horten (The Young Helmut)</em> <a class="header-anchor" href="#august-diehl-as-helmut-horten-the-young-helmut" aria-label="Permalink to &quot;[August Diehl](https://www.imdb.com/name/nm0225944/) as *Helmut Horten (The Young Helmut)*&quot;">​</a></h2><p><strong>The Role:</strong> The Department Store King and &quot;Market Optimizer.&quot;</p><p><strong>The Performance:</strong> Diehl brings his famous undercooled intensity. His Helmut is not an ideologue, but a &quot;manager of opportunities.&quot; In the 1930s scenes, he shows with terrifying calm how he &quot;acquires&quot; stores while the world around him collapses. He is the master of the &quot;pointillism of capital.&quot;</p><h2 id="oliver-masucci-as-the-multi-role-chronist" tabindex="-1"><a href="https://www.imdb.com/name/nm0557908/" target="_blank" rel="noreferrer">Oliver Masucci</a> as <em>the Multi-Role / Chronist</em> <a class="header-anchor" href="#oliver-masucci-as-the-multi-role-chronist" aria-label="Permalink to &quot;[Oliver Masucci](https://www.imdb.com/name/nm0557908/) as *the Multi-Role / Chronist*&quot;">​</a></h2><p><strong>The Roles:</strong></p><ul><li><strong>The Curator:</strong> Who manages Heidi&#39;s art and secrets.</li><li><strong>Alfred Alsberg:</strong> The former owner whose store Horten takes over.</li><li><strong>The Political Secretary:</strong> Who organizes the &quot;donations.&quot;</li></ul><p><strong>The Performance:</strong> Masucci is the chameleon of the film. Through his multiple roles, he embodies the different faces of power and its victims, always with a touch of dark humor.</p><hr><h2 id="udo-samel-as-august-woginger" tabindex="-1"><a href="https://www.imdb.com/name/nm0759797/" target="_blank" rel="noreferrer">Udo Samel</a> as <em>August Wöginger</em> <a class="header-anchor" href="#udo-samel-as-august-woginger" aria-label="Permalink to &quot;[Udo Samel](https://www.imdb.com/name/nm0759797/) as *August Wöginger*&quot;">​</a></h2><p><strong>The Role:</strong> The &quot;Bestimmungstäter&quot; (The Inciter). <strong>The Performance:</strong> Udo Samel portrays the ÖVP parliamentary group leader as a master of regional intervention. He plays Wöginger as a man who exercises power not through force, but through favors. In his gaze lies the cool logic of Upper Austrian power preservation. <strong>Quote from Set:</strong> <em>&quot;Wöginger truly believes he is only doing the best for his homeland. That makes the character so dangerous and fascinating at the same time.&quot;</em></p><hr><p><em>This cast ensures that &quot;The Horten Mystery&quot; is not just a documentary, but a high-carat cinematic event.</em></p>',17)])])}const d=t(s,[["render",i]]);export{g as __pageData,d as default};
